examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchAiAgentCard(
    agent = MonarchAiAgentRef(name = {{agent.name}}, id = {{agent.id}}, role = {{agent.role}}),
    description = {{description}},
    capabilities = listOf({{capabilities.0}}, {{capabilities.1}}, {{capabilities.2}}),
    tools = listOf(
        MonarchAiAgentTool({{tools.0.name}}, {{tools.0.description}}),
        MonarchAiAgentTool({{tools.1.name}}, {{tools.1.description}}),
    ),
    dataAccess = listOf({{dataAccess.0}}, {{dataAccess.1}}),
    owner = {{owner}},
) {
    MonarchButton(
        text = {{action.label}},
        onClick = {},
        variant = MonarchButtonVariant.{{action.variant|pascal}},
        size = MonarchButtonSize.{{action.size|pascal}},
    )
}

